(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id);
const ui={pHealth:$('playerHealth'),healthText:$('healthText'),bName:$('bossName'),bMode:$('bossMode'),bHealth:$('bossHealth'),round:$('roundPill'),toast:$('toast'),start:$('startOverlay'),upgrade:$('upgradeOverlay'),end:$('endOverlay'),cards:$('cards'),heal:$('healBtn')};
const W=960,H=540,FLOOR=454;
let scaleX=1,scaleY=1,raf=0,last=0,now=0,run=false,paused=false,round=0,order=[],boss=null,player=null,projectiles=[],particles=[],keys={},touch={},healCharges=2,startTime=0,elapsed=0,kills=0,sound=false,audio=null;
const bosses=[
 {name:'Rey Slime',kind:'slime',color:'#83e7b5',accent:'#c9ffde'}, {name:'Viuda de Ceniza',kind:'spider',color:'#d9a8ff',accent:'#f2d8ff'}, {name:'Caballero Hueco',kind:'knight',color:'#a9c8ff',accent:'#e1eeff'}, {name:'Mantis Carmesí',kind:'mantis',color:'#ff827d',accent:'#ffd1bb'}, {name:'Oráculo del Abismo',kind:'orb',color:'#84dcf2',accent:'#cefbff'}, {name:'Coloso de Sal',kind:'golem',color:'#e4c69d',accent:'#fff0cd'}, {name:'La Cacería',kind:'wolf',color:'#f59d73',accent:'#ffe1bd'}, {name:'Bruja de Raíces',kind:'witch',color:'#a4df83',accent:'#d8ffb5'}, {name:'Príncipe Espectral',kind:'ghost',color:'#c7c9ff',accent:'#f0f0ff'}, {name:'Dragón de Ónice',kind:'dragon',color:'#f27d9b',accent:'#ffc1cc'}
];
const finalBoss={name:'EL CORAZÓN UMBRAL',kind:'final',color:'#ffca76',accent:'#fff1be'};
const upgrades=[
 {id:'double',icon:'↑',tag:'MOVILIDAD',name:'Segundo aliento',desc:'Desbloquea un segundo salto en el aire.'},
 {id:'dash',icon:'↗',tag:'MOVILIDAD',name:'Paso espectral',desc:'Dash más largo e invulnerabilidad extendida.'},
 {id:'power',icon:'✦',tag:'OFENSIVA',name:'Filo lunar',desc:'Tus golpes hacen el doble de daño.'},
 {id:'heart',icon:'♥',tag:'VITALIDAD',name:'Corazón extra',desc:'Aumenta tu vida máxima en 1 y la restaura.'},
 {id:'speed',icon:'➤',tag:'MOVILIDAD',name:'Pies ligeros',desc:'Corre un 20% más rápido.'},
 {id:'reach',icon:'⟶',tag:'OFENSIVA',name:'Alcance sombrío',desc:'Tus ataques alcanzan más lejos.'},
 {id:'regen',icon:'✚',tag:'VITALIDAD',name:'Pulso vital',desc:'Recupera 1 vida al derrotar a un jefe.'},
 {id:'rapid',icon:'⟲',tag:'OFENSIVA',name:'Mano veloz',desc:'Reduce el tiempo entre ataques.'}
];
function resize(){const r=canvas.getBoundingClientRect();const d=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.floor(r.width*d));canvas.height=Math.max(1,Math.floor(r.height*d));scaleX=canvas.width/W;scaleY=canvas.height/H;ctx.setTransform(scaleX,0,0,scaleY,0,0)}
new ResizeObserver(resize).observe(canvas);resize();
function reset(){cancelAnimationFrame(raf);round=0;kills=0;healCharges=2;elapsed=0;startTime=performance.now();run=true;paused=false;order=bosses.map((_,i)=>i).sort(()=>Math.random()-.5).slice(0,9);player={x:170,y:FLOOR-58,vx:0,vy:0,w:33,h:58,hp:5,maxHp:5,dir:1,onGround:true,jumps:0,inv:0,attackCd:0,attackT:0,dashCd:0,dashT:0,stun:0,up:{double:false,dash:false,power:false,speed:false,reach:false,regen:false,rapid:false}};projectiles=[];particles=[];ui.end.classList.add('hidden');ui.start.classList.add('hidden');ui.upgrade.classList.add('hidden');launchRound();last=performance.now();raf=requestAnimationFrame(loop)}
function launchRound(){if(round<9){const data=bosses[order[round]],tier=round<3?1:round<6?2:3;boss={...data,tier,hp:100+round*14,maxHp:100+round*14,x:720,y:FLOOR-90,w:72,h:90,dir:-1,attackTimer:1.15,attackKind:0,telegraph:0,hitFlash:0,dead:false,phase:0,moveT:0};}else{boss={...finalBoss,tier:3,hp:260,maxHp:260,x:720,y:FLOOR-130,w:110,h:130,dir:-1,attackTimer:1,attackKind:0,telegraph:0,hitFlash:0,dead:false,phase:0,moveT:0};}
 projectiles=[];player.x=170;player.y=FLOOR-player.h;player.vx=0;player.vy=0;player.inv=1.2;player.onGround=true;updateHud();announce(round===9?'EL ÚLTIMO ENEMIGO':'RONDA '+String(round+1).padStart(2,'0')+' · '+boss.name);}
function updateHud(){ui.pHealth.style.width=Math.max(0,player.hp/player.maxHp*100)+'%';ui.healthText.textContent=`${player.hp} / ${player.maxHp}`;ui.bName.textContent=boss?boss.name:'—';const mode=boss?(boss.tier===1?'MODO I · ACECHO':boss.tier===2?'MODO II · DESPERTAR':'MODO III · FRENESÍ'):'—';ui.bMode.textContent=mode;ui.bHealth.style.width=boss?Math.max(0,boss.hp/boss.maxHp*100)+'%':'0%';ui.round.innerHTML=`RONDA <b>${String(Math.min(round+1,10)).padStart(2,'0')}</b> <span>/ 10</span>`;for(const id of ['double','dash','power','heart'])$('relic-'+id).classList.toggle('active',!!player.up[id]||(id==='heart'&&player.maxHp>5));}
function announce(text){ui.toast.textContent=text;ui.toast.classList.add('show');setTimeout(()=>ui.toast.classList.remove('show'),1350)}
function loop(t){if(!run)return;const dt=Math.min(.033,(t-last)/1000||0);last=t;now=t/1000;elapsed=(t-startTime)/1000;update(dt);draw();raf=requestAnimationFrame(loop)}
function update(dt){if(!boss||paused)return;const p=player;p.inv=Math.max(0,p.inv-dt);p.attackCd=Math.max(0,p.attackCd-dt);p.attackT=Math.max(0,p.attackT-dt);p.dashCd=Math.max(0,p.dashCd-dt);p.dashT=Math.max(0,p.dashT-dt);p.stun=Math.max(0,p.stun-dt);
 const left=keys.ArrowLeft||keys.KeyA||touch.left,right=keys.ArrowRight||keys.KeyD||touch.right,jump=keys.ArrowUp||keys.KeyW||keys.Space||touch.jump;
 if(p.dashT>0){p.vx=p.dir*(p.up.dash?650:510);p.vy=0;}else if(p.stun<=0){p.vx=(left?-1:0)+(right?1:0);if(p.vx)p.dir=Math.sign(p.vx);p.vx*=p.up.speed?260:215;}
 if(jump&&!p.jumpHeld&&(p.onGround||(p.up.double&&p.jumps<2))){p.vy=-485;p.onGround=false;p.jumps++;p.jumpHeld=true;burst(p.x+p.w/2,p.y+p.h,'#ffca76',7)}if(!jump)p.jumpHeld=false;
 if((keys.KeyK||touch.dash)&&!p.dashHeld&&p.dashCd<=0){p.dashT=p.up.dash?.25:.17;p.dashCd=p.up.dash?.65:1.1;p.inv=Math.max(p.inv,p.dashT+.05);p.dashHeld=true;burst(p.x+p.w/2,p.y+p.h/2,'#90e6e9',9)}if(!(keys.KeyK||touch.dash))p.dashHeld=false;
 if((keys.KeyJ||touch.attack)&&p.attackCd<=0){p.attackCd=p.up.rapid?.3:.48;p.attackT=.17;doAttack()}
 if(p.dashT<=0)p.vy+=1250*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.x=Math.max(22,Math.min(W-p.w-22,p.x));if(p.y+p.h>=FLOOR){p.y=FLOOR-p.h;p.vy=0;p.onGround=true;p.jumps=0}else p.onGround=false;
 updateBoss(dt);updateProjectiles(dt);for(let i=particles.length-1;i>=0;i--){const a=particles[i];a.life-=dt;a.x+=a.vx*dt;a.y+=a.vy*dt;a.vy+=a.gravity*dt;if(a.life<=0)particles.splice(i,1)}
 if(player.hp<=0){endGame(false)}updateHud();}
function doAttack(){const p=player,reach=p.up.reach?102:73,damage=p.up.power?28:15;const px=p.x+p.w/2+p.dir*reach*.48,py=p.y+p.h*.48;let hit=false;if(boss&&Math.abs((boss.x+boss.w/2)-px)<reach/2+boss.w*.37&&Math.abs((boss.y+boss.h*.52)-py)<(boss.h+p.h)/2+12){boss.hp-=damage;boss.hitFlash=.15;boss.x+=p.dir*10;hit=true;burst(boss.x+boss.w/2,boss.y+boss.h*.45,boss.color,8);if(boss.hp<=0)bossDefeated()}
 if(hit)beep(220,.04);}
function updateBoss(dt){if(!boss)return;const b=boss,p=player;b.hitFlash=Math.max(0,b.hitFlash-dt);b.moveT+=dt;b.attackTimer-=dt;
 const dist=p.x-b.x; b.dir=dist<0?-1:1;
 if(b.tier===1){b.x+=Math.sign(dist)*Math.min(Math.abs(dist),42*dt);}
 else if(b.tier===2){b.x+=Math.sign(dist)*Math.min(Math.abs(dist),55*dt);}
 else{b.x+=Math.sign(dist)*Math.min(Math.abs(dist),72*dt)}
 b.x=Math.max(80,Math.min(W-b.w-45,b.x));
 if(b.attackTimer<=0){b.attackTimer=(b.tier===1?2.45:b.tier===2?1.95:1.35)+Math.random()*.45;b.attackKind=(b.attackKind+1)%3;b.telegraph=b.kind==='slime'?0.45:b.tier===1?.68:b.tier===2?.52:.36;b.attackStarted=true;}
 if(b.telegraph>0){b.telegraph-=dt;if(b.telegraph<=0){const power=b.tier===1?1:b.tier===2?1.35:1.7;executeBossAttack(b,p,power);}}
 // boss-specific bounce / hover motion
 if(b.kind==='slime'&&b.telegraph>0)b.y=FLOOR-b.h-Math.sin(now*6)*12;else if(b.kind==='orb'||b.kind==='ghost'||b.kind==='final')b.y=FLOOR-b.h+Math.sin(now*2.7)*22;else b.y=FLOOR-b.h;
 if(b.kind==='spider'&&b.tier>=2&&b.telegraph>0)b.y-=18;
 if(Math.abs((p.x+p.w/2)-(b.x+b.w/2))<(p.w+b.w)*.42&&Math.abs(p.y+p.h-b.y-b.h)<33&&p.inv<=0&&b.telegraph<=0){hurtPlayer(1)}
}
function executeBossAttack(b,p,power){const kind=b.kind;let speed=b.tier===1?240:b.tier===2?310:390;const spawn=(x,y,vx,vy,r=9,color=b.color)=>projectiles.push({x,y,vx,vy,r,color,life:4,damage:1});
 const dx=p.x+p.w/2-(b.x+b.w/2),dir=Math.sign(dx)||-1;
 if(kind==='slime'||kind==='golem'||kind==='wolf'||kind==='knight'){b.vx=dir*(kind==='slime'?340:kind==='wolf'?480:360)*(b.tier===3?1.24:1);b.jumpY=kind==='slime'?-.75:0;if(b.tier>=2&&b.attackKind===1)spawn(b.x+b.w/2,b.y+b.h*.55,dir*speed*.9,-80,10);}
 else{const count=b.tier===1?1:b.tier===2?3:5;for(let i=0;i<count;i++){const spread=count===1?0:(i-(count-1)/2)*.24;const angle=Math.atan2(p.y+p.h*.5-(b.y+b.h*.55),p.x+p.w*.5-(b.x+b.w*.5))+spread;spawn(b.x+b.w/2,b.y+b.h*.55,Math.cos(angle)*speed,Math.sin(angle)*speed,kind==='final'?12:9);}}
 if(kind==='final'&&b.tier>=2){for(let i=0;i<3;i++)spawn(b.x+b.w/2,b.y+b.h*.5,dir*speed*.55,(i-1)*115,10)}
 b.vx=b.vx||0;b.telegraph=0;b.attackStarted=false;}
function updateProjectiles(dt){for(let i=projectiles.length-1;i>=0;i--){const q=projectiles[i];q.x+=q.vx*dt;q.y+=q.vy*dt;q.life-=dt;if(q.life<=0||q.x<0||q.x>W||q.y>FLOOR+30){projectiles.splice(i,1);continue}if(player.inv<=0&&player.dashT<=0&&circleRect(q,player)){projectiles.splice(i,1);hurtPlayer(1)}}if(boss?.vx){boss.x+=boss.vx*dt;boss.vx*=Math.pow(.025,dt);if(Math.abs(boss.vx)<8)boss.vx=0;}}
function circleRect(c,r){const x=Math.max(r.x,Math.min(c.x,r.x+r.w)),y=Math.max(r.y,Math.min(c.y,r.y+r.h));return (c.x-x)**2+(c.y-y)**2<c.r*c.r}
function hurtPlayer(amount){if(player.inv>0||player.dashT>0)return;player.hp=Math.max(0,player.hp-amount);player.inv=1.05;player.stun=.16;player.vx=player.x<boss.x?-230:230;player.vy=-190;burst(player.x+player.w/2,player.y+player.h/2,'#ff6677',12);beep(110,.12);updateHud()}
function bossDefeated(){if(!boss)return;kills++;burst(boss.x+boss.w/2,boss.y+boss.h/2,boss.color,34);beep(440,.18);if(round===9){boss=null;endGame(true);return;}round++;if(player.up.regen)player.hp=Math.min(player.maxHp,player.hp+1);updateHud();showRewards();}

function draw(){ctx.clearRect(0,0,W,H);drawWorld();if(boss)drawBoss(boss);drawProjectiles();drawPlayer();drawParticles();}
function drawWorld(){ctx.save();ctx.globalAlpha=.5;for(let i=0;i<8;i++){const x=((i*147+now*12)%W);ctx.fillStyle=i%2?'#e7d4be':'#9baec4';ctx.globalAlpha=.15+Math.sin(now+i)*.07;ctx.fillRect(x,80+(i*47)%180,2,2)}ctx.restore();ctx.strokeStyle='#e7c89455';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,FLOOR);ctx.lineTo(W,FLOOR);ctx.stroke();ctx.fillStyle='#ffcf8a12';ctx.fillRect(0,FLOOR+1,W,2);for(let i=0;i<22;i++){let x=(i*57+23)%W;ctx.fillStyle='#d9c7a220';ctx.fillRect(x,FLOOR+15+(i*13)%53,18+(i%3)*8,1)}}
function drawPlayer(){const p=player;if(!p)return;ctx.save();const cx=p.x+p.w/2,cy=p.y+p.h/2;if(p.inv>0&&Math.floor(now*18)%2===0)ctx.globalAlpha=.38;
 // shadow
 ctx.fillStyle='#080a15aa';ctx.beginPath();ctx.ellipse(cx,FLOOR+2,25,5,0,0,Math.PI*2);ctx.fill();
 ctx.translate(cx,cy);ctx.scale(p.dir,1);const bob=p.onGround?Math.sin(now*12)*1.5:0;
 // scarf and cloak
 ctx.fillStyle='#5e5878';ctx.beginPath();ctx.moveTo(-8,-5);ctx.quadraticCurveTo(-26,12,-20,29);ctx.lineTo(3,19);ctx.lineTo(9,-3);ctx.closePath();ctx.fill();ctx.fillStyle='#ffca76';ctx.beginPath();ctx.moveTo(-7,-12);ctx.quadraticCurveTo(-21,-18,-27,-10);ctx.lineTo(-8,-5);ctx.fill();
 // body
 ctx.fillStyle='#d9d4c8';ctx.beginPath();ctx.roundRect(-9,-7+bob,18,24,5);ctx.fill();ctx.fillStyle='#35384c';ctx.fillRect(-8,10+bob,16,6);
 // head / hood
 ctx.fillStyle='#282c3e';ctx.beginPath();ctx.arc(0,-17+bob,13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e9e1d1';ctx.beginPath();ctx.ellipse(3,-17+bob,7,8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#252638';ctx.fillRect(4,-19+bob,8,3);
 // legs
 ctx.fillStyle='#37384b';ctx.fillRect(-7,17+bob,6,17);ctx.fillRect(2,17+bob,6,17);ctx.fillStyle='#c8ad8d';ctx.fillRect(-9,31+bob,9,4);ctx.fillRect(1,31+bob,9,4);
 // sword swing
 if(p.attackT>0){ctx.strokeStyle='#ffedbd';ctx.lineWidth=4;ctx.lineCap='round';ctx.beginPath();ctx.arc(11,-1+bob,38,-.95,.72);ctx.stroke();ctx.strokeStyle='#fff9e8';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(11,-1+bob,43,-.86,.66);ctx.stroke();}else{ctx.strokeStyle='#d9d9e8';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(8,3);ctx.lineTo(22,16);ctx.stroke();ctx.strokeStyle='#ffca76';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(6,1);ctx.lineTo(13,8);ctx.stroke();}
 if(p.dashT>0){ctx.globalAlpha=.28;ctx.fillStyle='#91f4f1';ctx.beginPath();ctx.ellipse(-19,3,13,26,0,0,Math.PI*2);ctx.fill();}ctx.restore();}
function drawBoss(b){ctx.save();const cx=b.x+b.w/2,cy=b.y+b.h/2;if(b.hitFlash>0)ctx.globalAlpha=.55;if(b.telegraph>0){ctx.globalAlpha=.35+Math.sin(now*24)*.22;ctx.strokeStyle='#ffdf99';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(cx,cy,b.w*.7,b.h*.64,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;}
 // shadow
 ctx.fillStyle='#080a15a8';ctx.beginPath();ctx.ellipse(cx,FLOOR+2,b.w*.52,7,0,0,Math.PI*2);ctx.fill();ctx.translate(cx,cy);ctx.scale(b.dir,1);const c=b.color,a=b.accent,kind=b.kind,bob=(kind==='orb'||kind==='ghost'||kind==='final')?Math.sin(now*3)*7:Math.abs(Math.sin(now*5))*3;ctx.translate(0,bob);
 if(kind==='slime'){ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(-b.w*.5,b.h*.48);ctx.quadraticCurveTo(-b.w*.65,-b.h*.15,-b.w*.2,-b.h*.38);ctx.quadraticCurveTo(0,-b.h*.54,b.w*.2,-b.h*.38);ctx.quadraticCurveTo(b.w*.65,-b.h*.15,b.w*.5,b.h*.48);ctx.closePath();ctx.fill();ctx.fillStyle='#264b4a';ctx.fillRect(-17,-8,6,8);ctx.fillRect(8,-8,6,8);ctx.fillStyle=a;ctx.beginPath();ctx.ellipse(0,-b.h*.32,12,5,0,0,Math.PI*2);ctx.fill();}
 else if(kind==='spider'){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(0,10,26,35,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(0,-25,19,0,Math.PI*2);ctx.fill();for(let i=0;i<4;i++){const side=i<2?-1:1,yy=-2+(i%2)*18;ctx.strokeStyle=c;ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(side*15,yy);ctx.quadraticCurveTo(side*45,yy-20,side*37,yy+28);ctx.stroke()}ctx.fillStyle='#ffddc6';ctx.fillRect(5,-30,4,5);ctx.fillRect(-9,-30,4,5);}
 else if(kind==='knight'){ctx.fillStyle='#444b69';ctx.fillRect(-25,-22,50,59);ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(-28,-20);ctx.lineTo(0,-48);ctx.lineTo(29,-20);ctx.closePath();ctx.fill();ctx.fillStyle='#18202f';ctx.fillRect(-14,-10,28,5);ctx.fillStyle=a;ctx.fillRect(-9,-9,5,2);ctx.fillRect(5,-9,5,2);ctx.fillStyle='#8c9ab7';ctx.fillRect(-19,28,15,12);ctx.fillRect(5,28,15,12);ctx.strokeStyle='#dbe5ed';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(29,-11);ctx.lineTo(47,30);ctx.stroke();}
 else if(kind==='mantis'){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(0,4,22,34,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#482c3f';ctx.beginPath();ctx.arc(0,-31,17,0,Math.PI*2);ctx.fill();ctx.fillStyle=a;ctx.fillRect(-12,-34,6,5);ctx.fillRect(6,-34,6,5);ctx.strokeStyle=c;ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(-12,-2);ctx.lineTo(-39,-30);ctx.lineTo(-26,10);ctx.moveTo(12,-2);ctx.lineTo(38,-30);ctx.lineTo(25,10);ctx.stroke();}
 else if(kind==='orb'){ctx.shadowColor=c;ctx.shadowBlur=28;ctx.fillStyle=c;ctx.beginPath();ctx.arc(0,0,32,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#20253b';ctx.beginPath();ctx.arc(0,0,18,0,Math.PI*2);ctx.fill();ctx.fillStyle=a;ctx.beginPath();ctx.arc(0,0,8,0,Math.PI*2);ctx.fill();for(let i=0;i<3;i++){ctx.strokeStyle=c+'aa';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,43+i*7,16+i*7,now*(i%2?1:-1),0,Math.PI*2);ctx.stroke()}}
 else if(kind==='golem'){ctx.fillStyle=c;ctx.beginPath();ctx.roundRect(-30,-38,60,74,9);ctx.fill();ctx.fillStyle='#887764';ctx.fillRect(-24,-27,13,15);ctx.fillRect(11,1,16,17);ctx.fillStyle='#453c3c';ctx.fillRect(-15,-15,8,6);ctx.fillRect(8,-15,8,6);ctx.fillStyle=a;ctx.fillRect(-8,8,16,4);ctx.fillRect(-22,39,19,8);ctx.fillRect(5,39,19,8);}
 else if(kind==='wolf'){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(-1,5,39,21,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(25,-16,19,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(14,-30);ctx.lineTo(12,-54);ctx.lineTo(28,-34);ctx.moveTo(30,-30);ctx.lineTo(43,-48);ctx.lineTo(43,-24);ctx.fill();ctx.fillStyle=a;ctx.fillRect(27,-20,5,4);ctx.fillRect(30,8,5,3);ctx.fillStyle='#4d4247';ctx.fillRect(-25,20,7,22);ctx.fillRect(13,20,7,22);}
