function burst(x,y,color,n){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=50+Math.random()*240,life=.25+Math.random()*.55;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-50,r:2+Math.random()*3,color,life,max:life,gravity:430})}}
function showRewards(){run=false;ui.upgrade.classList.remove('hidden');$('rewardEyebrow').textContent=`VICTORIA · RONDA ${String(round).padStart(2,'0')} · ${boss?.name||'JEFE DERROTADO'}`;const available=upgrades.filter(u=>!player.up[u.id]&&!(u.id==='heart'&&player.maxHp>=8));const picks=[];while(picks.length<3){const source=available.length?available:upgrades;const item=source[Math.floor(Math.random()*source.length)];if(!picks.includes(item))picks.push(item)}ui.cards.innerHTML='';for(const item of picks){const el=document.createElement('button');el.className='card';el.innerHTML=`<div class="card-icon">${item.icon}</div><div class="card-tag">${item.tag}</div><h3>${item.name}</h3><p>${item.desc}</p><div class="choose">ELEGIR ↗</div>`;el.addEventListener('click',()=>chooseUpgrade(item));ui.cards.appendChild(el)}ui.heal.disabled=healCharges<=0;ui.heal.style.opacity=healCharges<=0?'.4':'1';ui.heal.innerHTML=`♥ &nbsp; Recuperar 2 de vida <span>(${healCharges} disponibles)</span>`;}
function chooseUpgrade(item){player.up[item.id]=true;if(item.id==='heart'){player.maxHp++;player.hp=Math.min(player.maxHp,player.hp+1)}if(item.id==='regen')player.hp=Math.min(player.maxHp,player.hp+1);ui.upgrade.classList.add('hidden');launchRound();run=true;last=performance.now();raf=requestAnimationFrame(loop);}
ui.heal.addEventListener('click',()=>{if(healCharges<=0)return;healCharges--;player.hp=Math.min(player.maxHp,player.hp+2);updateHud();ui.upgrade.classList.add('hidden');launchRound();run=true;last=performance.now();raf=requestAnimationFrame(loop)});
function endGame(won){run=false;ui.upgrade.classList.add('hidden');ui.end.classList.remove('hidden');$('endEyebrow').textContent=won?'EL CICLO SE HA ROTO':'LA NOCHE TE RECLAMA';$('endTitle').innerHTML=won?'EL SOL<br><span>RECUERDA.</span>':'FIN DE<br><span>LA CARRERA.</span>';$('endText').textContent=won?'El corazón umbral se apaga. Por primera vez en siglos, amanece. La leyenda lleva tu nombre.':'La oscuridad vuelve a cerrar sus puertas. Cada intento deja una lección. La próxima vez, el ciclo será tuyo.';$('endKills').textContent=`${kills} / 10`;$('endTime').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;}
$('startBtn').addEventListener('click',reset);$('restartBtn').addEventListener('click',reset);
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','Space'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.code==='KeyJ'&&!e.repeat)touch.attack=true});window.addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='KeyJ')touch.attack=false});
for(const btn of document.querySelectorAll('.touch-btn')){const k=btn.dataset.key;const on=e=>{e.preventDefault();touch[k]=true;btn.setPointerCapture?.(e.pointerId)};const off=e=>{e.preventDefault();touch[k]=false};btn.addEventListener('pointerdown',on);btn.addEventListener('pointerup',off);btn.addEventListener('pointercancel',off);btn.addEventListener('lostpointercapture',off);}
$('soundBtn').addEventListener('click',()=>{sound=!sound;$('soundBtn').textContent=`♫ SONIDO: ${sound?'ON':'OFF'}`;if(sound){audio=audio||new(window.AudioContext||window.webkitAudioContext)();audio.resume()}});
function beep(freq,duration){if(!sound||!audio)return;try{const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=freq;gain.gain.setValueAtTime(.055,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration)}catch(_){}}
// Draw a quiet idle scene while the title card is open.
player={x:170,y:FLOOR-58,vx:0,vy:0,w:33,h:58,hp:5,maxHp:5,dir:1,onGround:true,jumps:0,inv:0,attackCd:0,attackT:0,dashCd:0,dashT:0,stun:0,up:{}};boss={...bosses[0],tier:1,hp:100,maxHp:100,x:720,y:FLOOR-90,w:72,h:90,dir:-1,attackTimer:9,attackKind:0,telegraph:0,hitFlash:0};updateHud();draw();
})();

